D = [-2, -1, 0, 1, 2]
possible_p = set()

for d1 in D:
    for d2 in D:
        # Constraints: d2 != 0, not both d1 and d2 are zero (implied if d2!=0 unless d1=0)
        if d2 != 0:
            p = -d1 / d2

            # Constraint: p must be positive
            if p > 0:
                possible_p.add(p)

print(sorted(list(possible_p)))
